import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        String s = next();

        int len = s.length();
        int[] last = new int[26];
        for (int i = 0; i < len; i++) last[s.charAt(i) - 'a'] = i;
        boolean[] onStack = new boolean[26];
        char[] st = new char[len];
        int top = 0;
        for (int i = 0; i < len; i++) {
            char c = s.charAt(i);
            if (onStack[c - 'a']) continue;
            while (top > 0 && st[top - 1] > c && last[st[top - 1] - 'a'] > i) {
                onStack[st[top - 1] - 'a'] = false;
                top--;
            }
            st[top++] = c;
            onStack[c - 'a'] = true;
        }
        System.out.println(new String(st, 0, top));
    }
}
